t = int(input())
for i in range(t):
	(n, k) = map(int, input().split())
	a = list(map(int, input().split()))
	b = list(map(int, input().split()))
	d = {}
	for i in range(n):
		if a[i] not in d:
			d[a[i]] = b[i]
		else:
			d[a[i]] = min(b[i], d[a[i]])
	if len(d) < k:
		print(-1)
	else:
		array = []
		for dd in d:
			array.append(d[dd])
		array.sort()
		sum = 0
		for i in range(k):
			sum += array[i]
		print(sum)
